Boolean dei_sc_icon_stop( void )
{    
    Boolean ret ;
    
    dei_sc_info_set( DEI_SC_INFO_REMOTE_START , FALSE );
            
    ret = dei_sc_tx( DEI_SC_ACK_REMOTE_START_OFF , DEI_SC_PAGGING() || !DEI_SC_LOCK() ? DEI_SC_PAGGING_TX  : DEI_SC_NORMAL_TX, 100 ) ; 

    timeout_update ( dei_sc_timeout_lock , DEI_SC_TIMEOUT_LOCK );						
	  timeout_start  ( dei_sc_timeout_lock );

    return ret ;
}

